def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (everything after '+')
        if '+' in v:
            version_part, _ = v.split('+', 1)
        else:
            version_part = v

        # Split off pre-release (everything after '-')
        if '-' in version_part:
            base_part, prerelease_part = version_part.split('-', 1)
        else:
            base_part = version_part
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = base_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease_part:
            identifiers = prerelease_part.split('.')
            # Convert to comparable format: (is_numeric, numeric_value or string)
            parsed_identifiers = []
            for ident in identifiers:
                if ident.isdigit():
                    parsed_identifiers.append((0, int(ident)))
                else:
                    parsed_identifiers.append((1, ident))
        else:
            parsed_identifiers = None

        return (major, minor, patch, parsed_identifiers)

    def compare_key(v):
        major, minor, patch, prerelease = parse_version(v)

        # For sorting: (major, minor, patch, has_prerelease, prerelease_tuple)
        # has_prerelease: 0 if has prerelease, 1 if no prerelease
        # (version with prerelease sorts before without)
        if prerelease is None:
            return (major, minor, patch, 1, ())
        else:
            return (major, minor, patch, 0, tuple(prerelease))

    # Stable sort using compare_key
    return sorted(versions, key=compare_key)

